                  <div className={`p-3 border-b border-[var(--border)] bg-[var(--bg-app)] text-sm font-semibold text-[var(--text-primary)] ${isEditing ? 'cursor-move' : ''}`}>
                    {w.title}
                  </div>
                  <div className="flex-1 p-4 overflow-hidden relative">
                    {renderWidget(w)}
                  </div>
                </div>
              ))}
            </ResponsiveGridLayout>
          )}
        </div>
      </div>
    );
  }

  return (
