                 title={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
               >
                 {theme === 'dark' ? <Sun size={15} /> : <Moon size={15} />}
               </button>
              <div className="flex items-center gap-3 bg-[var(--bg-surface)] border border-[var(--border)] px-3 py-1.5 rounded-full">
