                      <p className="text-[10px] text-[var(--text-muted)] mt-0.5">
                        {src.size_human} · ~{src.lines_estimate?.toLocaleString()} lines
                      </p>
                    </div>
                  </label>
                ))
              )}
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-4 border-t border-[var(--border-subtle)] flex items-center justify-between">
              <button
