      </div>

      {deployments.length > 0 && (
        <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg p-6">
          <h3 className="text-lg font-bold text-[var(--text-primary)] mb-4">Recent Deployments</h3>
          <div className="flex gap-4 overflow-x-auto pb-2">
            {deployments.map(dep => (
              <div key={dep.id} className="min-w-[250px] border border-[var(--border)] rounded p-3 flex flex-col gap-2">
                <div className="flex justify-between items-center">
                  <span className="font-bold text-sm text-[var(--text-primary)]">{dep.service}</span>
                  <span className="text-xs font-mono bg-blue-500/10 text-blue-500 px-1.5 py-0.5 rounded">{dep.version}</span>
                </div>
                <div className="flex justify-between items-center text-xs text-[var(--text-secondary)]">
                  <span>{dep.environment}</span>
                  <span>{new Date(dep.timestamp).toLocaleTimeString()}</span>
                </div>
                {dep.description && <p className="text-xs text-[var(--text-secondary)] truncate">{dep.description}</p>}
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {loading ? (
          // Shimmer
          [...Array(2)].map((_, i) => (
            <div key={i} className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg p-6 animate-pulse h-48"></div>
          ))
        ) : rules.length === 0 ? (
          <div className="col-span-full py-12 text-center bg-[var(--bg-card)] border border-[var(--border)] rounded-lg">
            <LineChart className="mx-auto text-[var(--text-secondary)] opacity-50 mb-3" size={48} />
            <h3 className="text-lg font-medium text-[var(--text-primary)] mb-1">No Extraction Rules</h3>
            <p className="text-sm text-[var(--text-secondary)] mb-6 max-w-md mx-auto">Define rules to automatically extract numerical metrics from your logs in real-time, reducing the need for long-term log retention.</p>
            <button onClick={() => setShowCreateModal(true)} className="bg-fuchsia-600 hover:bg-fuchsia-700 text-white px-4 py-2 rounded text-sm font-medium transition-colors">Create First Rule</button>
          </div>
        ) : (
          rules.map(rule => (
            <div key={rule.id} className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg p-6 relative group">
              <button 
                onClick={() => deleteRule(rule.id)}
                className="absolute top-4 right-4 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <Trash2 size={16} />
              </button>

              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-lg font-bold text-[var(--text-primary)] mb-1">{rule.name}</h3>
                  <div className="flex items-center gap-3 text-xs text-[var(--text-secondary)]">
                    <span className="flex items-center gap-1 bg-[var(--bg-app)] px-2 py-1 rounded"><Terminal size={12} /> {rule.query}</span>
                    <span className="flex items-center gap-1"><Activity size={12} /> {rule.aggregation} (every {rule.window_seconds}s)</span>
                  </div>
                </div>
              </div>

              <div className="mt-6">
                <div className="text-xs text-[var(--text-secondary)] uppercase tracking-wider mb-2">Live Preview (24h)</div>
                {renderSparkline(metricData[rule.id] || [])}
              </div>
            </div>
          ))
        )}
      </div>

      {showCreateModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg shadow-xl w-full max-w-md overflow-hidden">
            <div className="p-4 border-b border-[var(--border)] flex justify-between items-center bg-[var(--bg-app)]">
              <h2 className="font-bold text-[var(--text-primary)]">Create Metric Rule</h2>
              <button onClick={() => setShowCreateModal(false)} className="text-[var(--text-secondary)] hover:text-[var(--text-primary)]">
                <X size={20} />
              </button>
            </div>
            <form onSubmit={createRule} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Metric Name</label>
                <input 
                  type="text" 
                  required
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-[var(--bg-app)] border border-[var(--border)] rounded-md py-2 px-3 text-sm text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-fuchsia-500"
                  placeholder="e.g. auth_failures_total"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Matching Query (DSL)</label>
                <input 
                  type="text" 
                  required
                  value={formData.query}
                  onChange={e => setFormData({...formData, query: e.target.value})}
                  className="w-full bg-[var(--bg-app)] border border-[var(--border)] rounded-md py-2 px-3 text-sm font-mono text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-fuchsia-500"
                  placeholder='e.g. level:ERROR AND "authentication failed"'
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Aggregation</label>
                  <select 
                    value={formData.aggregation}
                    onChange={e => setFormData({...formData, aggregation: e.target.value})}
                    className="w-full bg-[var(--bg-app)] border border-[var(--border)] rounded-md py-2 px-3 text-sm text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-fuchsia-500"
                  >
                    <option value="count">Count Matches</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Window (sec)</label>
                  <input 
                    type="number" 
                    min="10"
                    required
                    value={formData.window_seconds}
                    onChange={e => setFormData({...formData, window_seconds: parseInt(e.target.value)})}
                    className="w-full bg-[var(--bg-app)] border border-[var(--border)] rounded-md py-2 px-3 text-sm text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-fuchsia-500"
                  />
                </div>
              </div>

              <div className="pt-4 flex justify-end gap-3 border-t border-[var(--border)] mt-6">
                <button 
                  type="button" 
                  onClick={() => setShowCreateModal(false)}
                  className="px-4 py-2 rounded text-sm font-medium border border-[var(--border)] hover:bg-[var(--bg-app)] transition-colors text-[var(--text-primary)]"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="bg-fuchsia-600 hover:bg-fuchsia-700 text-white px-4 py-2 rounded text-sm font-medium transition-colors"
                >
                  Save Rule
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import ReactEcharts from 'echarts-for-react';
import * as echarts from 'echarts';
import { Database, TrendingUp, Zap, Loader2, AlertTriangle, RefreshCw, FileText, Cpu, MemoryStick, HardDrive, Wifi, Search } from 'lucide-react';
import { LineChart, Line, ResponsiveContainer, YAxis } from 'recharts';
import { apiFetch, runAnalysis as runAnalysisJob } from '@/lib/api';

const seededValue = (index: number, seed: number) => {
  const x = Math.sin(index * 12.9898 + seed * 78.233) * 43758.5453;
  return x - Math.floor(x);
};

const INITIAL_METRICS = Array.from({ length: 60 }, (_, i) => ({
  time: `05:${i.toString().padStart(2, '0')}`,
  cpu: i > 25 && i < 35 ? seededValue(i, 1) * 0.1 + 0.85 : seededValue(i, 2) * 0.2 + 0.3,
  mem: i > 26 ? seededValue(i, 3) * 0.1 + 0.8 : seededValue(i, 4) * 0.1 + 0.4,
  anomaly: (i === 26 || i === 28) ? 0.9 : null,
}));

function Sparkline({ data, dataKey, color }: { data: any[], dataKey: string, color: string }) {
  return (
    <div className="ml-auto">
      <LineChart width={120} height={40} data={data}>
        <Line type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2} dot={false} isAnimationActive={false} />
        <YAxis domain={['dataMin - 10', 'dataMax + 10']} hide />
      </LineChart>
    </div>
  );
}

export default function CommandCenter() {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchLoading, setSearchLoading] = useState(false);
  const [searchResults, setSearchResults] = useState<any[] | null>(null);
  const [sources, setSources] = useState<any[]>([]);
  const [selectedSource, setSelectedSource] = useState('');
  const [elapsedTime, setElapsedTime] = useState(0);
  const [settings, setSettings] = useState<any>(null);

  // Fetch settings on mount
  useEffect(() => {
    apiFetch('/settings')
      .then(setSettings)
      .catch(() => null);
  }, []);

  // Mock time series data for the metrics chart
  const [metrics] = useState<any[]>(INITIAL_METRICS);

  // Real-time sparkline data (Task 16)
  const [vitals, setVitals] = useState<any[]>(
    Array.from({ length: 20 }, () => ({ cpu: 0, mem: 0, disk: 0, net: 0 }))
  );

  useEffect(() => {
    const padToWindow = (arr: any[]) =>
      Array.from({ length: 20 }, (_, i) => {
        const v = arr[arr.length - 20 + i];
        return {
          cpu: v?.cpu ?? 0,
          mem: v?.mem ?? 0,
          disk: v?.disk ?? 0,
          net: v?.net ?? 0,
        };
      });

    const fetchVitals = async () => {
      try {
        const res = await apiFetch('/vitals');
        if (res?.vitals) setVitals(padToWindow(res.vitals));
      } catch {
        // Keep previous vitals if the backend is temporarily unavailable.
      }
    };

    fetchVitals();
    const intervalId = setInterval(fetchVitals, 5000);
    return () => clearInterval(intervalId);
  }, []);

  // Fetch available sources on mount
  useEffect(() => {
    apiFetch('/sources')
      .then((data) => {
        setSources(data);
        if (data.length > 0) setSelectedSource(data[0].path);
      })
      .catch(console.error);
  }, []);

  // Timer for loading state
  useEffect(() => {
    let interval: any;
    if (loading) {
      setElapsedTime(0);
      interval = setInterval(() => setElapsedTime(t => t + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const runAnalysis = async (source?: string) => {
    const target = source || selectedSource;
    if (!target) return;

    setLoading(true);
    setError(null);
    setData(null);
    try {
      const result = await runAnalysisJob({ source: target, intelligence: true });
      setData(result);
    } catch (err: any) {
      setError(err.message || 'Connection failed. Is the Python backend running on port 8000?');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) {
      setSearchResults(null);
      return;
    }
    setSearchLoading(true);
    try {
      const res = await apiFetch('/logs/query', {
        method: 'POST',
        body: JSON.stringify({ query: searchQuery, limit: 100 })
      });
      setSearchResults(res.results || []);
    } catch (err: any) {
      console.error('LQL Search failed', err);
    } finally {
      setSearchLoading(false);
    }
  };

  const getMetricOption = () => ({
    backgroundColor: 'transparent',
    tooltip: { trigger: 'axis' },
    legend: { 
      data: ['CPU', 'Memory', 'Anomalies'], 
      bottom: 0, 
      textStyle: { color: '#71717a', fontSize: 10 },
      icon: 'circle'
    },
    grid: { top: 20, bottom: 40, left: 30, right: 10 },
    xAxis: { 
      type: 'category', 
      data: metrics.filter((_, i) => i % 3 === 0).map(m => m.time),
      axisLabel: { color: '#52525b', fontSize: 9 },
      axisLine: { lineStyle: { color: '#27272a' } },
      axisTick: { show: false }
    },
    yAxis: { 
      type: 'value', 
      min: 0, max: 1,
      splitLine: { lineStyle: { color: '#27272a', type: 'dashed' } },
      axisLabel: { color: '#52525b', fontSize: 9 }
    },
    series: [
      { name: 'CPU', type: 'line', smooth: true, data: metrics.map(m => m.cpu), itemStyle: { color: '#3b82f6' }, symbol: 'circle', symbolSize: 4, areaStyle: { color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{ offset: 0, color: 'rgba(59, 130, 246, 0.3)' }, { offset: 1, color: 'rgba(59, 130, 246, 0)' }]) } },
      { name: 'Memory', type: 'line', smooth: true, data: metrics.map(m => m.mem), itemStyle: { color: '#10b981' }, symbol: 'circle', symbolSize: 4, areaStyle: { color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{ offset: 0, color: 'rgba(16, 185, 129, 0.3)' }, { offset: 1, color: 'rgba(16, 185, 129, 0)' }]) } },
      { name: 'Anomalies', type: 'scatter', data: metrics.map(m => m.anomaly), itemStyle: { color: '#d946ef' }, symbolSize: 8 }
    ]
  });

  const getTopologyOption = () => {
    // Use real cluster data if available
    if (data?.clusters) {
      const scatterData: any[] = [];
      data.clusters.forEach((c: any, idx: number) => {
        const count = Math.min(c.size, 50);
        for (let i = 0; i < count; i++) {
          const pointIndex = idx * 50 + i;
          scatterData.push([
            seededValue(pointIndex, 5) * 8 + idx * 2,
            seededValue(pointIndex, 6) * 8,
            seededValue(pointIndex, 7) * 3 + 2,
            c.cluster_id === -1 ? 'Noise' : `C${c.cluster_id}`
          ]);
        }
      });
      const groups = [...new Set(scatterData.map(d => d[3]))];
      const colors = ['#d946ef', '#3b82f6', '#10b981', '#f59e0b', '#ef4444'];
      return {
        backgroundColor: 'transparent',
        tooltip: { show: false },
        legend: { bottom: 0, left: 10, textStyle: { color: '#71717a', fontSize: 9 }, icon: 'circle' },
        grid: { top: 10, bottom: 30, left: 10, right: 10 },
        xAxis: { show: false }, yAxis: { show: false },
        series: groups.map((g, gi) => ({
          name: g,
          type: 'scatter',
          symbolSize: (d: any) => d[2] * 2,
          data: scatterData.filter(d => d[3] === g),
          itemStyle: { color: colors[gi % colors.length], opacity: g === 'Noise' ? 0.3 : 0.8 },
        })),
      };
    }
    // Fallback placeholder
    const scatterData = Array.from({ length: 150 }, (_, i) => [
      seededValue(i, 8) * 10,
      seededValue(i, 9) * 10,
      seededValue(i, 10) * 5 + 2,
      seededValue(i, 11) > 0.9 ? 'C1' : seededValue(i, 12) > 0.8 ? 'C2' : 'Noise'
    ]);
    return {
      backgroundColor: 'transparent',
      tooltip: { show: false },
      legend: { bottom: 0, left: 10, textStyle: { color: '#71717a', fontSize: 9 }, icon: 'circle' },
      grid: { top: 10, bottom: 30, left: 10, right: 10 },
      xAxis: { show: false }, yAxis: { show: false },
      series: [
        { name: 'C1', type: 'scatter', symbolSize: (d: any) => d[2] * 2, data: scatterData.filter(d => d[3] === 'C1'), itemStyle: { color: '#d946ef', opacity: 0.8 } },
        { name: 'C2', type: 'scatter', symbolSize: (d: any) => d[2] * 2, data: scatterData.filter(d => d[3] === 'C2'), itemStyle: { color: '#3b82f6', opacity: 0.8 } },
        { name: 'Noise', type: 'scatter', symbolSize: (d: any) => d[2] * 2, data: scatterData.filter(d => d[3] === 'Noise'), itemStyle: { color: '#10b981', opacity: 0.3 } }
      ]
    };
  };

  return (
    <div className="space-y-6 max-w-[1600px] mx-auto pb-10">

      {/* Source Selector + Run Button */}
      <div className="flex items-center gap-4">
        <div className="flex-1 flex items-center gap-3">
          <FileText size={16} className="text-[var(--text-muted)] shrink-0" />
          <select 
            value={selectedSource}
            onChange={(e) => setSelectedSource(e.target.value)}
            className="bg-[var(--bg-modal)] border border-[var(--border)] text-[var(--text-input)] text-xs rounded-lg px-4 py-2.5 outline-none flex-1 max-w-md appearance-none cursor-pointer"
          >
            {sources.map((src) => (
              <option key={src.path} value={src.path}>
                {src.name} ({src.size_human} · ~{src.lines_estimate?.toLocaleString()} lines)
              </option>
            ))}
          </select>
        </div>
        <button
          onClick={() => runAnalysis()}
          disabled={loading || !selectedSource}
          className="bg-fuchsia-600 hover:bg-fuchsia-500 disabled:opacity-50 text-white font-bold rounded-lg px-5 py-2.5 text-xs flex items-center gap-2 transition-colors cursor-pointer border-none"
        >
          {loading ? (
            <><Loader2 size={14} className="animate-spin" /> Analyzing... ({elapsedTime}s)</>
          ) : (
            <><RefreshCw size={14} /> Analyze</>
          )}
        </button>
      </div>

      {/* Log Query Language (LQL) Search */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-xl p-4 shadow-sm">
        <form onSubmit={handleSearch} className="relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--text-muted)]" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search logs with LQL (e.g., service:payment AND level:ERROR)..."
            className="w-full bg-[var(--bg-inset)] border border-[var(--border)] rounded-lg py-2.5 pl-11 pr-10 text-sm text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-fuchsia-500 transition-colors"
          />
          {searchLoading && (
            <Loader2 size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-fuchsia-500 animate-spin" />
          )}
        </form>
        {searchResults && (
          <div className="mt-4 pt-4 border-t border-[var(--border-subtle)] overflow-x-auto">
            <div className="flex justify-between items-center mb-2">
              <span className="text-xs font-semibold text-[var(--text-primary)]">LQL Results ({searchResults.length})</span>
              <button onClick={() => setSearchResults(null)} className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)]">Clear</button>
            </div>
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-[var(--border)]">
                  <th className="py-2 text-[var(--text-muted)] font-medium">Timestamp</th>
                  <th className="py-2 text-[var(--text-muted)] font-medium">Level</th>
                  <th className="py-2 text-[var(--text-muted)] font-medium">Message</th>
                </tr>
              </thead>
              <tbody>
                {searchResults.length === 0 ? (
                  <tr>
                    <td colSpan={3} className="py-4 text-center text-[var(--text-muted)] italic">No logs found matching this query.</td>
                  </tr>
                ) : (
                  searchResults.slice(0, 10).map((log, i) => (
                    <tr key={i} className="border-b border-[var(--border-subtle)] hover:bg-[var(--bg-surface)]">
                      <td className="py-2 pr-4 text-[var(--text-dimmed)] whitespace-nowrap">{new Date(log.timestamp).toLocaleTimeString()}</td>
                      <td className="py-2 pr-4">
                        <span className={`px-1.5 py-0.5 rounded-sm text-[10px] font-bold ${log.level === 'ERROR' ? 'bg-red-500/10 text-red-500' : 'bg-blue-500/10 text-blue-500'}`}>{log.level || 'INFO'}</span>
                      </td>
                      <td className="py-2 text-[var(--text-primary)] break-all font-mono opacity-80">{log.message}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
            {searchResults.length > 10 && (
              <p className="text-[10px] text-[var(--text-muted)] mt-2 text-center">Showing first 10 of {searchResults.length} results. Use specific filters to narrow down.</p>
            )}
          </div>
        )}
      </div>

      {/* System Vitals Panel */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-xl p-4 shadow-sm flex items-center justify-between">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Cpu size={14} className="text-blue-400" />
              <p className="text-xs text-[var(--text-muted)] font-medium uppercase tracking-wider">CPU Usage</p>
            </div>
            <span className="text-2xl font-bold text-[var(--text-primary)]">{vitals[vitals.length-1].cpu.toFixed(1)}%</span>
          </div>
          <Sparkline data={vitals} dataKey="cpu" color="#3b82f6" />
        </div>
        <div className="bg-[var(--bg-card)] border border-[var(--border-subtle)] rounded-xl p-4 shadow-sm flex items-center justify-between">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <MemoryStick size={14} className="text-emerald-400" />
